package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Category    string  `json:"category"`
	Price       float64 `json:"price"`
	InternalSKU string  `json:"internal_sku,omitempty"`
	SupplierRef string  `json:"supplier_ref,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeCategory attempts basic validation but is bypassable
func sanitizeCategory(input string) string {
	// Block obvious attacks - but doesn't handle all cases
	blocked := []string{"DROP", "DELETE", "INSERT", "UPDATE", "ALTER", "EXEC"}
	upper := strings.ToUpper(input)
	for _, kw := range blocked {
		if strings.Contains(upper, kw) {
			return "general"
		}
	}
	return input
}

// handleProductSearch handles product catalog searches
// Supports filtering by category and sorting
func handleProductSearch(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	order := r.URL.Query().Get("order")

	if category == "" {
		category = "all"
	}
	if sortBy == "" {
		sortBy = "name"
	}
	if order == "" {
		order = "ASC"
	}

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "category": true, "id": true}
	if !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// Validate order direction
	if strings.ToUpper(order) != "ASC" && strings.ToUpper(order) != "DESC" {
		order = "ASC"
	}

	category = sanitizeCategory(category)

	// Build query - category is interpolated (vulnerable)
	var query string
	if category == "all" {
		query = fmt.Sprintf("SELECT id, name, category, price FROM products ORDER BY %s %s LIMIT 50", sortBy, order)
	} else {
		query = fmt.Sprintf("SELECT id, name, category, price FROM products WHERE category = '%s' ORDER BY %s %s LIMIT 50", category, sortBy, order)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Category, &p.Price); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// handleHealthCheck for LB health probes
func handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", handleProductSearch)
	http.HandleFunc("/health", handleHealthCheck)
	log.Println("Starting product catalog service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
